        'Lysithea': '莉丝缇亚', 'Marianne': '玛莉安奴', 'Leonie': '雷欧妮', 'Flayn': '芙莲',
        'Manuela': '玛努艾拉', 'Catherine': '卡多莉奴', 'Shamir': '萨米亚', 'Byleth': '贝雷丝',
        'Rhea': '蕾雅', 'Sothis': '苏谛斯', 'Anna': '安娜', 'Constance': '康丝坦洁', 'Hapi': '哈琵'
    };
    const skillNameMap = {
        'support': '支援度', 'hand': '手部技巧', 'vagina': '阴部技巧', 'breast': '胸部技巧', 'leg': '腿部技巧',
        'mouth': '口部技巧', 'anal': '肛部技巧', 'foot': '足部技巧', 'seduction': '诱惑力', 'endurance': '耐受力',
