        'Hapi': 'https://files.catbox.moe/xvwl7z.png'
    };

    const dataContainer = document.querySelector('.status-data');
    if (!dataContainer) return;

    function parseData(text) {
        const data = { characters: {} };
        const blockRegex = /\[(\w+)\]([\s\S]*?)\[\/\1\]/g;
        let match;
        while ((match = blockRegex.exec(text)) !== null) {
            const blockName = match[1];
            const blockContent = match[2].trim();
            const lines = blockContent.split('\n');
            const blockData = {};
            let isSkillsBlock = false;
            lines.forEach(line => {
                const trimmedLine = line.trim();
                if (!trimmedLine) return;
                if (trimmedLine.startsWith('skills:')) {
                    isSkillsBlock = true;
                    blockData.skills = {};
                    return;
                }
                if (!line.startsWith(' ') && !line.startsWith('\t')) { isSkillsBlock = false; }
                const parts = trimmedLine.split(':');
                const key = parts[0].trim();
                const value = parts.slice(1).join(':').trim();
                if (isSkillsBlock && key && value) {
                    blockData.skills[key] = value;
                } else if (key && value) {
                    blockData[key] = value;
                }
            });
            if (blockName === 'General') {
                data.general = blockData;
            } else {
                data.characters[blockName] = blockData;
            }
        }
        return data;
    }

    function renderStatus(data) {
        const globalInfoEl = document.querySelector('.fe-global-info');
        const tabsEl = document.querySelector('.fe-character-tabs');
        globalInfoEl.innerHTML = `
            <span><strong>导师:</strong> ${data.general.user_name}</span>
            <span><strong>学级:</strong> ${data.general.class}</span>
            <span><strong>时间:</strong> ${data.general.time}</span>
            <span><strong>地点:</strong> ${data.general.location}</span>`;
        tabsEl.innerHTML = '';
        Object.keys(data.characters).forEach((charName, index) => {
            const tab = document.createElement('div');
            tab.className = 'fe-tab';
            if (index === 0) tab.classList.add('active');
            tab.dataset.char = charName;
            tab.textContent = nameMap[charName] || charName;
            tab.addEventListener('click', () => {
                document.querySelectorAll('.fe-tab').forEach(t => t.classList.remove('active'));
                tab.classList.add('active');
                renderCharacter(charName, data.characters[charName]);
            });
            tabsEl.appendChild(tab);
        });
        const firstChar = Object.keys(data.characters)[0];
        if (firstChar) {
            renderCharacter(firstChar, data.characters[firstChar]);
        }
    }

    function renderProgressBar(name, valueStr) {
        const [level, exp] = (valueStr || 'E/0').split('/');
        const percentage = parseInt(exp) || 0;
        return `
            <div class="fe-skill-item">
                <div class="skill-name">${skillNameMap[name] || name}</div>
                <div class="fe-progress-bar">
                    <div class="fe-progress-fill" style="width: ${percentage}%;"></div>
                    <div class="fe-progress-text">${level} (${exp}/100)</div>
                </div>
            </div>`;
    }

    function renderCharacter(charName, charData) {
        const detailsEl = document.querySelector('.fe-character-details');
        if (!charData) {
            detailsEl.innerHTML = '无角色数据。';
            return;
        }
        const skills = charData.skills || {};
        const supportHtml = renderProgressBar('support', charData.support);
        const skillsHtml = Object.entries(skills)
            .map(([skillName, skillValue]) => renderProgressBar(skillName, skillValue))
            .join('');
        detailsEl.innerHTML = `
            <div class="fe-left-panel">
                <div class="fe-avatar-frame">
                    <img class="fe-avatar" src="${avatarMap[charName] || ''}" alt="${nameMap[charName] || charName}">
                </div>
                <div class="fe-job">${charData.job || '未知'}</div>
            </div>
            <div class="fe-right-panel">
                 ${supportHtml}
                <div class="fe-skill-grid">
                    ${skillsHtml}
                </div>
                <div class="fe-info-block">
                    <p><strong>衣着:</strong> ${charData.outfit || '无'}</p>
                    <p><strong>行动:</strong> ${charData.action || '无'}</p>
                    <p><strong>想法:</strong> ${charData.thoughts || '无'}</p>
                </div>
            </div>`;
    }

    const rawData = dataContainer.textContent.trim();
    if (rawData) {
        const parsedData = parseData(rawData);
        renderStatus(parsedData);
    }
});
</script>

</body>
</html>
